<template>
 <div class="nw-document" :class="{'has-panel':panelOpen&&!readingOpen&&layout!=='immersive'}">
  <div class="nw-editor-pane">
   <header class="nw-doc-toolbar"><div class="nw-breadcrumb"><button class="nw-icon nw-mobile-directory" aria-label="笔记目录" @click="$emit('directory')"><Icon name="menu" :size="17"/></button><span>我的笔记</span><Icon name="chevron-right" :size="12"/><span>{{ folderLabel }}</span></div><div class="nw-doc-actions"><button class="nw-icon" :aria-label="form.favorite?'取消收藏':'收藏笔记'" :class="{active:form.favorite}" @click="form.favorite=!form.favorite"><Icon name="star" :size="17"/></button><button class="nw-button" :aria-pressed="layout==='fullscreen'" @mousedown.prevent @click="$emit('layout',layout==='fullscreen'?'normal':'fullscreen')"><Icon name="maximize" :size="16"/><span>{{ layout==='fullscreen'?'退出全屏':'全屏' }}</span></button><button class="nw-button" :aria-pressed="layout==='immersive'" @mousedown.prevent @click="$emit('layout',layout==='immersive'?'normal':'immersive')"><Icon name="minimize-2" :size="16"/><span>{{ layout==='immersive'?'退出沉浸':'沉浸' }}</span></button><button class="nw-icon" aria-label="切换辅助面板" :aria-expanded="panelOpen" @click="$emit('panel')"><Icon name="list" :size="17"/></button><details class="nw-menu"><summary aria-label="更多笔记操作"><Icon name="more-horizontal" :size="18"/></summary><div><button @click="menuAction($event,loadHistory)">版本历史</button><button @click="menuAction($event,exportMarkdown)">导出 Markdown</button><button @click="menuAction($event,exportCopy)">导出恢复副本</button><button @click="menuAction($event,()=> $emit('delete'))">移入回收站</button></div></details></div></header>
   <div ref="scrollRoot" class="nw-doc-scroll" tabindex="-1">
    <p v-if="loading" class="nw-loading" role="status">正在读取笔记…</p><div v-else-if="loadError" class="nw-loading nw-error" role="alert">{{ loadError }}<button class="nw-button" @click="load">重试读取</button></div>
    <template v-else>
     <div v-if="recovered" class="nw-recovery" role="status"><Icon name="history" :size="16"/><span>发现此账户的本地恢复副本（版本 {{ recovered.revision }}）</span><button class="nw-button" @click="restoreDraft">恢复到编辑器</button><button class="nw-icon" aria-label="暂不恢复" @click="recovered=null"><Icon name="x" :size="14"/></button></div>
     <section v-if="session.paused.value||session.conflict.value" class="nw-conflict" aria-label="保存冲突" role="alert"><h3>这篇笔记已在其他位置修改，或恢复副本需要核对。</h3><p>已暂停自动保存。你的编辑内容会保留为恢复副本。</p><div class="nw-compare"><div><h4>当前编辑内容</h4><pre>{{ form.content }}</pre></div><div><h4>服务器版本 {{ session.conflict.value?.revision||'待读取' }}</h4><pre>{{ session.conflict.value?.content||'请读取服务器内容后再核对' }}</pre></div></div><button class="nw-button" @click="exportCopy">保留本地修改副本</button><button class="nw-button" @click="reloadServer">查看当前服务器内容</button><button class="nw-primary" :disabled="!session.conflict.value" @click="acceptServer">重新加载最新版本</button></section>
     <div class="nw-article-head kf-input-surface"><input v-model="form.title" class="nw-title" aria-label="笔记标题" placeholder="无标题笔记" maxlength="200"/><div class="nw-article-tags"><span v-for="(tag,i) in form.tags" :key="tag" class="nw-tag-chip"># {{ tag }}<button :aria-label="`移除标签${tag}`" @click="form.tags.splice(i,1)"><Icon name="x" :size="11"/></button></span><input v-model="tagInput" aria-label="添加标签" placeholder="+ 添加标签" maxlength="100" @keydown.enter.prevent="addTag" @blur="addTag"/></div>
      <div class="nw-article-meta"><span><Icon name="lock" :size="13"/>私有</span><span><Icon name="clock" :size="13"/>{{ form.updateTime?`更新于 ${noteTime(form.updateTime)}`:'尚未保存' }}</span><span><Icon name="file-text" :size="13"/>{{ form.content.length }} 字</span><select :value="form.status" aria-label="笔记状态" @change="form.status=($event.target as HTMLSelectElement).value as 'DRAFT'|'SAVED'"><option value="SAVED">笔记</option><option value="DRAFT">草稿</option></select><select :value="form.folderId??''" aria-label="笔记文件夹" @change="form.folderId=Number(($event.target as HTMLSelectElement).value)||null"><option value="">未分类</option><option v-for="f in folders" :key="f.id" :value="f.id">{{ f.name }}</option></select></div>
     </div>
     <NoteEditor v-if="session.ready.value" ref="editor" v-model="form.content" initial-mode="visual" :note-id="session.id.value" :revision="session.revision.value" :allow-save="!session.dirty.value&&!session.busy.value&&!session.paused.value" @reading-saved="acceptReadingAnswer" @reading-open="readingOpen=$event" @selection="selection=$event"/>
    </template>
   </div>
   <footer class="nw-save-state" aria-live="polite"><span :class="{'nw-error':!!session.error.value}"><Icon :name="session.busy.value?'refresh-cw':session.dirty.value?'clock':'check-circle'" :size="14"/>{{ session.status.value }}</span><span v-if="session.error.value" class="nw-error">{{ session.error.value }}</span><button v-if="session.error.value&&!session.paused.value" class="nw-text-button" @click="manualSave">点击重试</button><button class="nw-save-button nw-primary" :disabled="!session.ready.value||session.busy.value||session.paused.value" @click="manualSave"><Icon name="save" :size="14"/>{{ session.busy.value?'保存中…':'保存' }}</button><small>⌘ / Ctrl S</small></footer>
  </div>
  <aside v-show="panelOpen&&!readingOpen&&layout!=='immersive'" class="nw-right" aria-label="笔记辅助面板"><div class="nw-panel-tabs"><button :class="{active:panel==='outline'}" @click="panel='outline'">大纲</button><button :class="{active:panel==='relations'}" @click="panel='relations'">关联</button><button :class="{active:panel==='ai'}" @click="panel='ai'">AI 助手</button><button class="nw-icon" aria-label="关闭辅助面板" @click="$emit('panel')"><Icon name="x" :size="13"/></button></div><div class="nw-panel-body"><NotesOutline v-show="panel==='outline'" :content="form.content" @select="editor?.jumpToHeading($event)"/><NotesRelations v-if="panel==='relations'" :note-id="session.id.value" @open-note="$emit('openNote',$event)"/><NotesAiPanel v-if="panel==='ai'&&!readingOpen" :content="form.content" :title="form.title" :revision="session.revision.value" :note-id="session.id.value" :selection="selection" @apply="applyAi"/>
   <section v-if="panel==='outline'" class="nw-info"><h3>笔记信息</h3><dl><dt>创建</dt><dd>{{ form.createTime?noteTime(form.createTime):'尚未保存' }}</dd><dt>更新</dt><dd>{{ form.updateTime?noteTime(form.updateTime):'尚未保存' }}</dd><dt>位置</dt><dd>{{ folderLabel }}</dd><dt>版本</dt><dd>{{ session.id.value?session.revision.value:'尚未保存' }}</dd></dl><p v-if="form.sourceTitle" class="nw-hint">来源：{{ form.sourceTitle }}</p><button class="nw-button" :disabled="!session.id.value" @click="loadHistory"><Icon name="history" :size="14"/>版本历史</button></section>
  </div></aside>
  <AppDialog :open="historyOpen" title="版本历史" :scrollable="true" :hide-footer="true" @cancel="historyOpen=false"><p v-if="historyError" role="alert">{{ historyError }}<button class="nw-button" @click="loadHistory">重试</button></p><p v-if="!history.length&&!historyError" class="nw-hint">暂无版本记录</p><details v-for="v in history" :key="v.id" class="nw-history"><summary>版本 {{ v.revision }} · {{ noteTime(v.createTime) }} · {{ reasonLabels[v.reason]||v.reason }}</summary><h4>{{ v.title }}</h4><pre>{{ v.content }}</pre><button class="nw-button" :disabled="session.busy.value||session.dirty.value" @click="restoreVersion(v)">恢复为新版本</button></details></AppDialog>
 </div>
</template>
<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import Icon from '@/components/ui/Icon.vue'
import AppDialog from '@/components/ui/AppDialog.vue'
import NoteEditor from './NoteEditor.vue'
import NotesOutline from './NotesOutline.vue'
import NotesRelations from './NotesRelations.vue'
import NotesAiPanel,{type NoteAiProposal} from './NotesAiPanel.vue'
import {notesApi,type ServerNote,type NotePayload,type NoteVersion,type NoteFolder} from '@/api/notes'
import {useNoteSession} from '@/notes/useNoteSession'
import {noteTags,serializeTags,noteTime} from '@/notes/model'
import type {NotesLayoutMode} from '@/notes/workspace-layout'
import type {NoteSelection} from '@/notes/editor-types'
import {confirmDialog,notify,getApiError} from '@/utils/toast'
const props=defineProps<{noteId:number|null;owner:number;folders:NoteFolder[];initialFolder?:number|null;draftKey?:string;panelOpen:boolean;layout:NotesLayoutMode}>(),emit=defineEmits<{saved:[ServerNote];layout:[NotesLayoutMode];panel:[];directory:[];openNote:[number];delete:[]}>()
const form=ref({title:'',content:'',tags:[] as string[],favorite:false,folderId:null as number|null,sourceDocId:null as number|null,sourceTitle:'',status:'SAVED' as 'SAVED'|'DRAFT',createTime:'',updateTime:''})
const readingOpen=ref(false)
const tagInput=ref(''),loading=ref(true),loadError=ref(''),selection=ref<NoteSelection|null>(null),panel=ref<'outline'|'relations'|'ai'>('outline'),scrollRoot=ref<HTMLElement|null>(null),editor=ref<InstanceType<typeof NoteEditor>|null>(null)
const read=():NotePayload=>({title:form.value.title,content:form.value.content,tags:serializeTags(form.value.tags),favorite:form.value.favorite,folderId:form.value.folderId,sourceDocId:form.value.sourceDocId,sourceTitle:form.value.sourceTitle,status:form.value.status})
function acceptReadingAnswer(n:ServerNote){if(session.dirty.value){notify('笔记已在本地修改，请从版本历史核对已保存的导师回答','warning');return}session.acceptServer(n);emit('saved',n)}
function apply(n:ServerNote){if(n.userId!==props.owner)throw Error('账户与笔记归属不一致，请刷新工作台');form.value={title:n.title,content:n.content,tags:noteTags(n.tags),favorite:!!n.favorite,folderId:n.folderId??null,sourceDocId:n.sourceDocId??null,sourceTitle:n.sourceTitle||'',status:n.status||'SAVED',createTime:n.createTime,updateTime:n.updateTime};selection.value=null}
const identity=props.draftKey&&props.draftKey!=='legacy'?`new:${props.draftKey}`:undefined
const session=useNoteSession(props.owner,props.noteId,read,apply,n=>{form.value.createTime=n.createTime;form.value.updateTime=n.updateTime;emit('saved',n)},identity)
type Recovery={userId:number;id:number|null;revision:number;needsReview?:boolean;saved?:boolean;payload:NotePayload}
const recovered=ref<Recovery|null>(null),historyOpen=ref(false),historyError=ref(''),history=ref<NoteVersion[]>([])
const reasonLabels:Record<string,string>={CREATE:'创建',UPDATE:'更新',DELETE:'移入回收站',RESTORE:'恢复笔记',VERSION_RESTORE:'历史恢复',LEGACY_IMPORT:'旧数据导入',UPGRADE_BASELINE:'升级前原文'}
const folderLabel=computed(()=>{const path:string[]=[],seen=new Set<number>();let id=form.value.folderId;while(id&&!seen.has(id)){seen.add(id);const f=props.folders.find(f=>f.id===id);if(!f)break;path.unshift(f.name);id=f.parentId;}return path.join(' / ')||'未分类'})
let disposed=false
async function load(){loading.value=true;loadError.value='';try{
 const raw=localStorage.getItem(session.key.value);let recovery:Recovery|null=null;if(raw)try{const value=JSON.parse(raw);if(value.userId===props.owner&&value.payload&&typeof value.payload.title==='string'&&typeof value.payload.content==='string')recovery=value}catch{notify('本地恢复副本无法解析；原数据未修改','warning')}
 if(props.noteId){const n=await notesApi.detail(props.noteId);if(disposed)return;session.start(n)}else if(recovery?.saved&&recovery.id){const n=await notesApi.detail(recovery.id);if(disposed)return;session.start(n);emit('saved',n);const linked=localStorage.getItem(session.key.value);if(linked){const value=JSON.parse(linked);if(value.userId===props.owner&&value.payload&&(!value.saved||value.needsReview))recovery=value}}else{
  form.value.title='无标题笔记';form.value.status='DRAFT';form.value.folderId=props.initialFolder??null;const prefillKey=`notes-document-prefill:${props.owner}`,prefill=sessionStorage.getItem(prefillKey);if(prefill&&!recovery){const d=JSON.parse(prefill);form.value.title=d.fromDocTitle?`${d.fromDocTitle} - 学习笔记`:'无标题笔记';form.value.content=d.content||'';form.value.tags=Array.isArray(d.tags)?d.tags:[];form.value.sourceTitle=d.fromDocTitle||'';form.value.sourceDocId=Number(d.fromDocId)||null;sessionStorage.removeItem(prefillKey)}session.start(undefined,!recovery)
 }
 if(recovery&&(!recovery.saved||recovery.needsReview))recovered.value=recovery;
 }catch(e){loadError.value=getApiError(e,'笔记加载失败')}finally{if(!disposed)loading.value=false}}
function addTag(){const name=tagInput.value.trim();if(name&&!form.value.tags.includes(name)&&form.value.tags.length<50)form.value.tags.push(name);tagInput.value=''}
async function manualSave(){if(!form.value.title.trim()){session.error.value='请输入笔记标题';session.backup();return false;}return session.save()}
async function protect(){if(!session.ready.value)return true;if(session.busy.value||session.dirty.value){if(await manualSave())return true;session.backup();return confirmDialog('笔记尚未保存到服务器。保留恢复副本并离开吗？',{title:'保留未保存内容',confirmText:'保留副本并离开',cancelText:'继续编辑'})}return true}
function restoreDraft(){const d=recovered.value;if(!d)return;if(d.needsReview||d.revision!==session.revision.value){session.paused.value=true;session.recoveryRevision.value=d.revision;}form.value.title=d.payload.title;form.value.content=d.payload.content;form.value.tags=noteTags(d.payload.tags);form.value.sourceTitle=d.payload.sourceTitle||'';if(d.payload.status)form.value.status=d.payload.status;if(d.payload.folderId!==undefined)form.value.folderId=d.payload.folderId;if(d.payload.favorite!==undefined)form.value.favorite=d.payload.favorite;if(d.payload.sourceDocId!==undefined)form.value.sourceDocId=d.payload.sourceDocId;session.backup();if(session.paused.value)void reloadServer();recovered.value=null}
async function reloadServer(){if(!session.id.value)return;session.backup();try{session.conflict.value=await notesApi.detail(session.id.value)}catch(e){session.error.value=getApiError(e,'无法读取服务器版本')}}
function acceptServer(){if(session.conflict.value){session.backup();session.acceptServer(session.conflict.value)}}
async function loadHistory(){if(!session.id.value)return;historyOpen.value=true;historyError.value='';try{history.value=await notesApi.versions(session.id.value)}catch(e){historyError.value=getApiError(e,'历史读取失败')}}
async function restoreVersion(v:NoteVersion){if(!session.id.value||!await confirmDialog('恢复此版本并生成新修订？当前内容仍会保留在历史中。'))return;try{const n=await notesApi.restoreVersion(session.id.value,v.revision,session.revision.value);session.acceptServer(n);emit('saved',n);await loadHistory()}catch(e){historyError.value=getApiError(e,'恢复失败')}}
function download(content:string,name:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportMarkdown(){download(`# ${form.value.title}\n\n${form.value.content}`,`${form.value.title.replace(/[\\/:*?"<>|]/g,'_')||'笔记'}.md`,'text/markdown;charset=utf-8')}
function exportCopy(){download(JSON.stringify({id:session.id.value,revision:session.recoveryRevision.value??session.revision.value,needsReview:session.paused.value,...read()},null,2),'knowflow-note-recovery.json','application/json')}
function applyAi(p:NoteAiProposal){if(p.original!==form.value.content||p.noteId!==session.id.value||p.revision!==session.revision.value){notify('笔记已改变，请重新生成建议','warning');return}if(p.kind==='optimize'){if(p.selection){if(!editor.value?.applySelection(p.text,p.selection))notify('选区已改变，请重新选择后生成','warning')}else form.value.content=p.text;}else{const labels:Record<string,string>={summary:'AI摘要',explain:'术语解释',knowledge:'知识要点',quiz:'自测题',interview:'面试题',question:'笔记问答'};form.value.content+=`\n\n## ${labels[p.kind]||'AI建议'}\n\n${p.text}`}}
function menuAction(event:Event,run:()=>void){(event.currentTarget as HTMLElement).closest('details')?.removeAttribute('open');run()}
function keydown(event:KeyboardEvent){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='s'){event.preventDefault();void manualSave()}}
function beforeUnload(event:BeforeUnloadEvent){if(session.dirty.value){session.backup();event.preventDefault();event.returnValue=''}}
onMounted(()=>{void load();window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',beforeUnload)});onBeforeUnmount(()=>{disposed=true;window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',beforeUnload)})
async function organize(patch:{favorite?:boolean;folderId?:number|null}){if(patch.favorite!==undefined)form.value.favorite=patch.favorite;if(patch.folderId!==undefined)form.value.folderId=patch.folderId;return manualSave()}
function receive(n:ServerNote){if(session.dirty.value||session.busy.value){session.paused.value=true;session.conflict.value=n;session.backup()}else session.acceptServer(n)}
defineExpose({organize,receive,protect,save:manualSave,getId:()=>session.id.value,getNote:()=>({...read(),id:session.id.value,revision:session.revision.value}),session,scrollRoot})
</script>
